```python
import pathlib,struct,json,posixpath,hashlib
class Asar:
    def __init__(self,path):
        self.path=pathlib.Path(path)
        with self.path.open('rb') as f:
            h=struct.unpack('<4I',f.read(16));self.header=json.loads(f.read(h[3]));self.offset=8+h[1]
    def node(self,path):
        obj=self.header
        for part in path.split('/'):
            if part:obj=obj['files'][part]
        if 'link' in obj:return self.node(obj['link'])
        return obj
    def read(self,path):
        obj=self.node(path)
        if obj.get('unpacked'):return pathlib.Path(str(self.path)+'.unpacked',*path.split('/')).read_bytes()
        with self.path.open('rb') as f:
            f.seek(self.offset+int(obj['offset']));return f.read(obj['size'])
    def files(self,path):
        def walk(node,prefix):
            if 'link' in node:yield from walk(self.node(node['link']),prefix)
            elif 'files' in node:
                for k,v in node['files'].items():yield from walk(v,prefix+'/'+k)
            else:yield prefix
        yield from walk(self.node(path),path)
    def extract(self,path,dest):
        dest=pathlib.Path(dest).resolve();dest.mkdir(parents=True,exist_ok=True)
        for src in self.files(path):
            rel=src[len(path):].lstrip('/');out=(dest/rel).resolve()
            if not out.is_relative_to(dest):raise ValueError('unsafe archive path')
            out.parent.mkdir(parents=True,exist_ok=True);out.write_bytes(self.read(src))

if __name__=='__main__':
    a=Asar(__import__('os').environ['DSH_ASAR'])
    for p in ['','dsh','dsh/node_modules','dsh/node_modules/@deepseek-ai']:
        try:print(p,list(a.node(p).get('files',{}))[:100])
        except KeyError:pass
    for p in ['dsh/node_modules/@deepseek-ai/cordis','dsh/node_modules/@deepseek-ai/dsh-web']:
        try:print(p,a.node(p).keys(),json.loads(a.read(p+'/package.json')))
        except Exception as e:print(str(e))

