<details><summary>extract_host_deps.py</summary>

```python
from asar_tools import Asar
import pathlib,json,re,sys,hashlib,os
r=pathlib.Path(__file__).resolve().parent
a=Asar(os.environ['DSH_ASAR'])
queue=sys.argv[1:] or ['@deepseek-ai/cordis','@deepseek-ai/cordis-plugin-loader','@deepseek-ai/schemastery','@deepseek-ai/dsh-web','@deepseek-ai/dsh-credentials','@deepseek-ai/dsh-launch-environment']
seen=set();manifest={}
while queue:
    pkg=queue.pop(0)
    if pkg in seen or pkg.startswith('node:'):continue
    seen.add(pkg);prefix='dsh/node_modules/'+pkg
    try:meta=json.loads(a.read(prefix+'/package.json'))
    except KeyError:
        print('NOT-BUNDLED',pkg);continue
    dest=r/'node_modules'/pathlib.Path(pkg)
    a.extract(prefix,dest)
    manifest[pkg]={'version':meta.get('version'),'package_sha256':hashlib.sha256(a.read(prefix+'/package.json')).hexdigest()}
    imports=set(meta.get('dependencies',{}))
    for p in dest.rglob('*'):
        if p.suffix not in ['.js','.mjs','.cjs']:continue
        text=p.read_text(encoding='utf-8',errors='replace')
        for m in re.finditer(r'''(?:from\s*|import\s*\(\s*|require\(\s*)['"]([^'".][^'"]*)['"]''',text):
            spec=m.group(1)
            if spec.startswith('node:'):continue
            parts=spec.split('/');name='/'.join(parts[:2]) if spec.startswith('@') else parts[0]
            try:a.node('dsh/node_modules/'+name);imports.add(name)
            except KeyError:pass
    queue.extend(sorted(imports-seen))
    print(pkg,meta.get('version'),flush=True)
old=r/'host_dependency_manifest.json'
prior=json.loads(old.read_text(encoding='utf-8')) if old.exists() else {}
prior.update(manifest);old.write_text(json.dumps(prior,ensure_ascii=False,indent=2),encoding='utf-8')

