```

### Reproducer 3 - Untaken branch rebind erases parameter `non_owned_origin` (O5.1 `HYB-E3004` bypass)

```hy
fn worker(m map[string]int, done chan<- bool) {
    for i in 0..5000 {
        m["k"] = i
    }
    done <- true
}

fn spawn_it(m map[string]int, done chan<- bool) {
    if false {
        m = map[string]int{"k": 1}
    }
    task worker(move m, done)
}

fn main() {
    m := map[string]int{"k": 0}
    done := make(chan bool, 1)
    spawn_it(m, done)
    for i in 0..5000 {
        m["k"] = i
    }
    <-done
