/**
 * Normalizes indirect map links (URL shorteners, Apple Maps place links, and
 * {@code osm.org/go/<token>} short codes) into a canonical form that the
 * existing Organic Maps URL parser already understands.
 *
 * <p>This class performs no caching and holds no state. It is safe to call
 * from any thread. Network access, when required, is bounded by
 * {@link #NETWORK_TIMEOUT_MS} and is performed only for a whitelist of known
 * short-link hosts; every other input is returned unchanged so that no
 * regression is possible for links that already work.</p>
 */
public final class UrlShortLinkResolver
{
  private static final String TAG = UrlShortLinkResolver.class.getSimpleName();

  private static final int NETWORK_TIMEOUT_MS = 5000;
  private static final int MAX_REDIRECTS = 8;

  private UrlShortLinkResolver() {}

