      // 24 bits each in three-to-four byte payloads. When fewer bytes are
      // available (which is what the short tokens use), we fall back to a
      // best-effort decode; if it produces an out-of-range coordinate we
      // abandon the fast path and let the network resolver handle it.
      final double lat = latQ / 1e7;
      final double lon = 0.0; // Longer payloads carry longitude in trailing bytes; short tokens do not.
