        return String.format(Locale.US, "geo:%f,%f", lat, lon);

      // The 3-byte variant does not carry enough bits for a full lat/lon pair.
      // Fall through to the network resolver for a correct expansion.
      return followRedirects(uri.toString());
    }
    catch (IllegalArgumentException e)
    {
